<?php
namespace App\Http\Controllers\SupervisorPortal;
use App\Http\Controllers\Controller; use App\Http\Controllers\SupervisorPortal\Concerns\AuthorizesAssignedStudents; use App\Models\Student; use Illuminate\Http\Request; use Illuminate\View\View;
class StudentController extends Controller { use AuthorizesAssignedStudents; public function index(Request $r): View { $ids=$r->user()->supervisedClassrooms()->pluck('classrooms.id'); $students=Student::with(['user','classroom'])->whereIn('classroom_id',$ids)->when($r->q,function($x,$v){$x->where(fn($q)=>$q->where('student_number','like',"%$v%")->orWhereHas('user',fn($u)=>$u->where('name','like',"%$v%")));})->paginate(25)->withQueryString(); return view('supervisor.students.index',compact('students')); } public function show(Request $r,Student $student): View { $this->authorizeStudent($r,$student); $student->load(['user','classroom','guardians.user','attendances'=>fn($q)=>$q->latest('date')->limit(20),'studentNotes'=>fn($q)=>$q->latest(),'guardianCalls'=>fn($q)=>$q->latest()]); return view('supervisor.students.show',compact('student')); } }
